import fs from 'node:fs';
import assert from 'node:assert/strict';
import { checkedInspection, contractRows, profileSections, selectedHistory, validity } from '../../apps/memory_graph/src/mapInspectorModel.js';
const { schema, node, location, edge, legacy, history } = JSON.parse(fs.readFileSync(0, 'utf8'));
const catalog = schema.field_catalog;
assert.equal(checkedInspection(node, { kind: 'node', id: 'avery' }), node);
assert.equal(checkedInspection(edge, { kind: 'edge', id: 'avery-round' }), edge);
assert.throws(() => checkedInspection(node, { kind: 'node', id: 'place' }));
assert.throws(() => checkedInspection(node, { kind: 'edge', id: 'avery-round' }));
assert.throws(() => checkedInspection(edge, { kind: 'node', id: 'avery' }));
assert.throws(() => checkedInspection(edge, { kind: 'edge', id: 'avery-employer' }));
assert.equal(contractRows(node, { ...catalog, digest_sha256: 'wrong' }), null);
const rows = contractRows(node, catalog), all = contractRows(node, catalog, true);
assert.equal(rows.find(r => r.id === 'contact.email').values[0].text, 'avery@example.org');
assert.equal(rows.some(r => r.id === 'contact.phone'), false);
assert.equal(all.find(r => r.id === 'contact.phone').empty, 'not_recorded');
const profile = profileSections(rows, node.entity);
assert.equal(profile.flatMap(([, fields]) => fields).some(f => f.id === 'identity.name'), false);
assert.equal(profile.find(([name]) => name === 'About')[1].some(f => f.id === 'identity.description'), true);
assert.equal(profile.find(([name]) => name === 'Contact')[1].some(f => f.id === 'contact.email'), true);
assert.equal(profileSections(rows, node.entity, { hidden: ['contact.email'] }).flatMap(([, fields]) => fields).some(f => f.id === 'contact.email'), false);
const ambiguous = { ...node.entity, classification: { ambiguous: true } };
assert.equal(profileSections(rows, ambiguous, { hidden: ['identity.type'] }).flatMap(([, fields]) => fields).some(f => f.id === 'identity.type'), true);
const unknown = structuredClone(rows.find(r => r.id === 'contact.email'));
unknown.values[0].claim.provenance ||= {};
unknown.values[0].claim.provenance.knowledge ||= {};
unknown.values[0].claim.provenance.knowledge.qualifiers ||= {};
unknown.values[0].claim.provenance.knowledge.qualifiers.field_contract = { state: 'unknown' };
assert.equal(profileSections([unknown], node.entity, { hidden: ['contact.email'] })[0][1][0].important, true);
const placeFields = contractRows(location, catalog, true).map(f => f.id);
assert.equal(placeFields.includes('profile.location'), true);
assert.equal(placeFields.includes('contact.email'), false);
assert.equal(placeFields.includes('relationship.contained-in'), true);
assert.equal(contractRows(edge, catalog, true).length, 1);
assert.equal(edge.field_view.coverage.selection_only, true);
assert.equal(legacy.field_view.unmapped_claim_ids.includes('avery-robin'), true);
assert.equal(validity(edge.claims.assertions[0]).until, 'Not recorded');
assert.equal(validity({ valid_to: null }).until, 'Explicitly unknown');
assert.equal(validity({ provenance: { knowledge: { qualifiers: { field_contract: { validity_end: 'ongoing' } } } } }).until, 'Explicitly ongoing');
const onlyEdge = selectedHistory(history, { kind: 'edge', id: 'avery-round' });
assert.deepEqual(onlyEdge.flatMap(op => op.actions.map(a => a.id)), ['avery-round']);
const lineage = { operations: [{ id: 'op', actions: [{ type: 'assertion', id: 'new', predecessors: ['old'] }, { type: 'assertion', id: 'old', predecessors: ['first'] }, { type: 'assertion', id: 'first' }, { type: 'assertion', id: 'unrelated' }] }] };
assert.deepEqual(selectedHistory(lineage, { kind: 'edge', id: 'new' })[0].actions.map(a => a.id), ['new', 'old', 'first']);
assert.equal(selectedHistory(history, { kind: 'node', id: 'avery' }).every(op => op.actions.every(a => a.subject === 'avery')), true);
console.log(JSON.stringify({ result: 'passed' }));
